CREATE OR REPLACE FUNCTION __mj_bizappssonar."spCreateIntervention"(
    p_id UUID DEFAULT NULL,
    p_scoresegmentid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_triggertype varchar(20) DEFAULT NULL,
    p_actionid_clear boolean DEFAULT false,
    p_actionid UUID DEFAULT NULL,
    p_controlgrouppercent_clear boolean DEFAULT false,
    p_controlgrouppercent decimal(5, 2) DEFAULT NULL,
    p_status varchar(16) DEFAULT NULL,
    p_actionparamsjson_clear boolean DEFAULT false,
    p_actionparamsjson TEXT DEFAULT NULL,
    p_kind varchar(20) DEFAULT NULL
) RETURNS SETOF __mj_bizappssonar."vwInterventions" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO __mj_bizappssonar."Intervention"
        (
            "ID",
            "ScoreSegmentID",
                "Name",
                "Description",
                "TriggerType",
                "ActionID",
                "ControlGroupPercent",
                "Status",
                "ActionParamsJSON",
                "Kind"
        )
    VALUES
        (
            v_new_id,
            p_scoresegmentid,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                COALESCE(p_triggertype, 'Manual'),
                CASE WHEN p_actionid_clear = true THEN NULL ELSE COALESCE(p_actionid, NULL) END,
                CASE WHEN p_controlgrouppercent_clear = true THEN NULL ELSE COALESCE(p_controlgrouppercent, NULL) END,
                COALESCE(p_status, 'Draft'),
                CASE WHEN p_actionparamsjson_clear = true THEN NULL ELSE COALESCE(p_actionparamsjson, NULL) END,
                COALESCE(p_kind, 'Action')
        )
    ;

    RETURN QUERY
    SELECT * FROM __mj_bizappssonar."vwInterventions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
