) RETURNS SETOF __mj_bizappssonar."vwScoreSegments" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO __mj_bizappssonar."ScoreSegment"
        (
            "ID",
            "ScoreModelID",
                "Name",
                "Description",
                "FilterExpression",
                "IsDynamic",
                "MemberCountCached",
