        (
            v_new_id,
            p_scoremodelid,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_filterexpression_clear = true THEN NULL ELSE COALESCE(p_filterexpression, NULL) END,
                COALESCE(p_isdynamic, TRUE),
                CASE WHEN p_membercountcached_clear = true THEN NULL ELSE COALESCE(p_membercountcached, NULL) END,
                CASE WHEN p_lastevaluatedat_clear = true THEN NULL ELSE COALESCE(p_lastevaluatedat, NULL) END
        )
    ;

    RETURN QUERY
